<?php
namespace Src\Inventario\Infrastructure\Requests;use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Rule;
class RegistrarMovimientoRequest extends FormRequest{public function authorize():bool{return$this->user()?->can('inventario.gestionar')??false;}protected function prepareForValidation():void{$costo=$this->input('costoUnitario');$this->merge(['repuesto_id'=>$this->input('repuestoId'),'costo_unitario'=>$costo===''?null:$costo]);}public function rules():array{return['repuesto_id'=>['required','uuid',Rule::exists('repuestos','id')->where('estado','activo')],'tipo'=>['required',Rule::in(['entrada','ajuste'])],'cantidad'=>['required','decimal:0,3','not_in:0','between:-99999999999.999,99999999999.999'],'costo_unitario'=>['nullable','decimal:0,2','min:0','max:999999999999.99'],'motivo'=>['required','string']];}}
